insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 1, $json${"week":6,"day":1,"title":"Six nights","heading":"Six nights","question":"he looked straight at the window. Are you found?","steps":[{"t":"say","text":"Nobody breathes.\n\nUp in the square the watchman stands with his lantern raised, and his face turned down the hill to the wall. To your window.\n\nSomebody pinches the lamp out between finger and thumb.\n\nThen he calls out, one short word, and all round the square other lanterns lift."},{"t":"say","text":"Nobody lights a candle that night. For hours the lanterns move along the foot of the wall and up onto the wall-walk, and you sit in the dark and listen to them come and go.\n\nTwice, boots scrape right past the room's hidden door.\n\nTwice, they walk on."},{"t":"notice","lines":{"Might":{"first":"The hidden door is one slab, a hand thick, hung so that a child could swing it.","second":"It was made to be shut in a hurry, and held."},"Agility":{"first":"The boots on the walk came at the same pace both times.","second":"They are searching by rote. They do not expect to find anything."},"Intellect":{"first":"They hunted the whole wall, and not this stretch more than any other.","second":"He saw a light. He did not see where."},"Charm":{"first":"Your palm is stiff under its white linen.","second":"All of you are wearing it now. The same linen as the children."},"Craft":{"first":"The floor by the slit is worn into two shallow hollows.","second":"Somebody sat here, on watch, for a lifetime. Then somebody else did."},"Aim":{"first":"From the slit, the hall's doors sit square in the middle of the view.","second":"This window was cut for one thing."}}},{"t":"say","text":"Morning in the dead city looks like evening anywhere else. The fifth is in a pack, wrapped in cloth, and you can feel the cold of it through the canvas.\n\nThey kept it in this room for as long as they lived. In the stone niche where it lay, pressed flat beneath it all that time, is something as thin as a leaf."},{"t":"act","label":"LIFT IT OUT"},{"t":"say","text":"It comes away from the stone with a dry whisper, and it is colder than the niche that held it.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"They lived in this room. If the Seekers left a way into his hall, the first step of it would be here."},{"t":"challenge","title":"THE ROOM THEY KEPT","desc":"Four walls, a floor, and boots that may come back.","options":[{"attr":"Intellect","verb":"think as they did: where would a watcher leave word for the next watcher?"},{"attr":"Aim","verb":"from the doorway, sight along the walls and the floor for the one line that is out of true"}],"reward":"+500g","fail":"it takes the whole grey day, and the boots come back while you are still looking","harderIf":{"key":"G5:united-effort-lost","has":true,"by":2,"line":"**Two harder.** The hill is already hunting you."}},{"t":"say","text":"You find it before the grey light at the slit has moved, and before any boot comes back along the wall.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It takes the whole grey day, room and floor and wall, with an ear always on the stair. Late on, the boots come back. They stop outside the hidden door. Everyone in the room stands with a hand over the nearest lamp.\n\nThey walk on.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Scratched small into the stone under the slit window, where only someone sitting watch would see it, is an arrow.\n\nIt points down. Into the wall itself, toward the long halls under the ramparts where the city's defenders slept."},{"t":"act","label":"WHERE WOULD ANYONE RUN TO, FROM A CITY LIKE THIS?"},{"t":"say","text":"Garrick is looking out of the slit window, at the hall. *\"Somewhere they'd never be found,\"* he says."},{"t":"say","text":"At dusk, far up in the square, a lantern stops beside the Order's board. A watchman is taking up the chalk.\n\nYou are holding the watch-page from the dead watchman's fist. It still shows seven, and nobody is left to mark it."},{"t":"act","label":"STRIKE THE PAGE"},{"t":"say","text":"A burnt stick from the bottom of somebody's pack. One stroke.\n\nSix.\n\nYou are keeping the enemy's count now."},{"t":"say","text":"Garrick watches the stroke go on. *\"I kept a tally behind my bar for years,\"* he says. *\"Most of it was who owed me.\"*"},{"t":"say","text":"It is a long wall, and from the square every slit in it looks the same. In all its centuries here the Order has never known this room was there. It still does not.\n\nYou have a safe room in the enemy's city."},{"t":"say","text":"**The hall is sealed, and the Seekers left a way in, somewhere. The arrow points down: the defenders' barracks, under the wall.**","pull":true},{"t":"summary","lines":["**SIX NIGHTS** · Day 1","You earned: `[gold]` · Intellect or Aim `[growth]`","You learned: **you are not found.** The Order searched the wall all night and walked past this room twice. It has never known the room was here. Under the window, an arrow points down into the wall.","You hold: the fifth · the watch-page: **six left**","Fragment: 1 found, locked","Tomorrow: **the barracks under the wall**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 2, $json${"week":6,"day":2,"title":"Five nights","heading":"Five nights","question":"where does the arrow lead?","steps":[{"t":"say","text":"You go out by the gate-tower in the grey morning, and down to the crossroads where the rest of the soldiers stood, mid-stride, for longer than anyone has been alive.\n\nThe street is empty."},{"t":"notice","lines":{"Might":{"first":"A dozen men in iron walked out of this street, and not a cobble is chipped.","second":"They went carefully."},"Agility":{"first":"One line of prints leaves each place where a soldier stood, and goes uphill.","second":"Slow, even steps. Nothing hurried them."},"Intellect":{"first":"Some of this company came at you by the wall, and you broke them.","second":"These are the ones that stayed. Until now."},"Charm":{"first":"Nobody says anything.","second":"Everybody has counted the doorways."},"Craft":{"first":"Where each one stood, the cobbles are a shade paler, in the shape of two boots.","second":"They kept the weather off that stone for longer than anyone has been alive."},"Aim":{"first":"Up the hill, three streets on, something stands across the road.","second":"It was not there before."}}},{"t":"say","text":"The defenders' barracks are long, low halls cut into the back of the city wall: rows of stone bunks, racks where spears once stood, a kitchen whose fire went out on the war's last night. The air smells of cold stone and very old smoke.\n\nThe far end is blocked. A beam has come down, and half the ceiling with it."},{"t":"challenge","title":"THE COLLAPSE","desc":"There is a room beyond it.","options":[{"attr":"Might","verb":"shift the beam"},{"attr":"Craft","verb":"find the way through that brings nothing more down"}],"reward":"+500g","fail":"part of the ceiling comes down, and all of Highwall hears it"},{"t":"say","text":"The way clears. Not quietly: stone on stone never is.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"Part of the ceiling comes down in a roar of dust. When it settles, the way is clear, and everyone is grey.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Then, on the stair behind you: iron on stone. Slow. One step at a time.\n\nIt stands in the doorway, in armour gone green and black. Its helm is turned to the fallen stone.\n\nNot to you.\n\nNobody makes a sound."},{"t":"act","label":"DO NOT MOVE"},{"t":"say","text":"The heartbeat comes.\n\nIt turns. It climbs the stair. You hear it go on up the hill, one step at a time, until you cannot hear it."},{"t":"say","text":"The room beyond the fall is dark. Garrick turns out a handful of candle stubs from his coat pockets and lights one for each of you, and holds his own low, so that it does not show at the stair."},{"t":"say","text":"At the far end, in a small room of its own, the bunks are not in rows. They have been pulled into a rough circle round a cold hearth, as if the people who slept here wanted to be near each other.\n\nIn the hearthstone is a housing."},{"t":"act","label":"PRESS IT WITH YOUR THUMB"},{"t":"say","text":"It slides out. What is inside is as cold as a hearth that has not seen a fire in centuries.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"On the way back you pass the rest of the soldiers: three streets further up the hill than they were, as still as before.\n\nEvery helm is turned to the hall."},{"t":"say","text":"At dusk, back in the wall room, the burnt stick snaps halfway through the stroke."},{"t":"act","label":"FINISH IT WITH THE STUB"},{"t":"say","text":"Five."},{"t":"say","text":"**They are not coming for you. They are going to him. And wherever the Seekers' way in begins, it begins at his walls. The great square, after dark.**","pull":true},{"t":"summary","lines":["**FIVE NIGHTS** · Day 2","You earned: `[gold]` · Might or Craft `[growth]`","You learned: **the dead move when nobody is watching, and they are not coming for you.** One stood in the doorway and did not see you. The rest are three streets nearer the hall. And you have stood in the room where the Seekers slept before the last night.","You hold: the fifth · the watch-page: **five left**","Fragments: 2 found","Tomorrow: **the great square**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 3, $json${"week":6,"day":3,"title":"Four nights","heading":"Four nights","question":"is there any way in at the hall itself?","steps":[{"t":"say","text":"You wait out the grey day in the wall room. At dusk the heartbeat comes, and beyond the slit it shakes the dust off the rooftops in thin grey sheets.\n\nThe page is on the sill, with the stub beside it."},{"t":"act","label":"STRIKE THE PAGE"},{"t":"say","text":"Four."},{"t":"say","text":"You go up to the great square after dark. The Order's fire is burning in the ruined house across from the hall, and there are twice as many round it as there were."},{"t":"say","text":"Before you cross, you can watch one thing properly."},{"t":"choice","id":0,"labels":["THE WATCH","THE BOARD"],"mode":"pick","branches":[{"options":[0],"text":"You time it. The man coming on says, *\"Keep the dark,\"* and the man going off answers, *\"It keeps us,\"* and for as long as that takes, neither of them is looking at the square."},{"options":[1],"text":"You read it by their firelight. Four strokes left uncrossed. The same as the page in your coat.\n\nThey struck theirs at dusk. So did you."}]},{"t":"notice","lines":{"Might":{"first":"The doors are taller than houses, and there is no bar, no chain, no lock on them.","second":"Nothing that a strong arm could break."},"Agility":{"first":"The fountain throws a shadow two-thirds of the way across.","second":"The last third is open."},"Intellect":{"first":"Twice the watchmen, and they are still only watching.","second":"They could have searched this city for you. They have not left the fire."},"Charm":{"first":"The new men sit a little apart from the old ones.","second":"They have not kept this watch before. They are afraid of the hall."},"Craft":{"first":"The seam between the doors has been filled, flush, with something that is not mortar.","second":"Whoever shut these did not mean them to open again."},"Aim":{"first":"A watchman walks the square with a lantern, and turns at the same flagstone every time.","second":"Past that stone, he never looks."}}},{"t":"challenge","title":"THE SQUARE","desc":"Sixty paces to the hall's wall, past the fire.","options":[{"attr":"Agility","verb":"the fountain's shadow, then the open ground, fast"},{"attr":"Charm","verb":"keep everyone calm and still while the lantern goes by"}],"reward":"+500g","fail":"the lantern swings your way, and you lose an hour flat against the stone"},{"t":"say","text":"You are across, and in the lee of the hall's great wall, unseen.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"The lantern swings your way. You spend an hour pressed flat against the cold flags. The watchman goes back to his fire at last, and calls two more men up out of the dark streets to sit with him.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Garrick comes over last of all, and sets his back against the wall beside you."},{"t":"press","title":"THE FIRE","detail":"from here you can see their faces: count them, and look at each","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Eleven. Six of them have road-dust to the knee, and packs not yet unrolled.\n\nThey did not send for more men to hunt you. These were already coming.","cond":{"on":"press"}},{"t":"say","text":"The hall's wall goes up out of sight above you."},{"t":"act","label":"LAY YOUR PALM FLAT ON IT"},{"t":"say","text":"The stone is warm.\n\nNot sun-warm. There has been no sun for days. Something on the other side of this wall is warm, and has been for a very long time.\n\nThen the heartbeat comes, and you feel it in the stone under your hand before you hear it."},{"t":"say","text":"Low in the wall, near the ground, is a housing. It turns a quarter-turn, with a scrape you are sure the whole square heard.\n\nThe stone round it is warm. What is inside is not.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"There is no way in on this side. The doors are shut with something older than locks.\n\nBut the Seekers shut the front. And the hall's back wall runs straight into the hill."},{"t":"say","text":"You cross back on the change of the watch, while the two men are looking at each other, and sleep in the wall room with the warmth of that stone still in your palm.\n\n**He is on the other side of this wall. Inside, on the night the moon goes dark, with the fifth: that is the whole plan now. The cracked hill behind the hall.**","pull":true},{"t":"summary","lines":["**FOUR NIGHTS** · Day 3","You earned: `[gold]` · Agility or Charm `[growth]`","You learned: **the hall's wall is warm, and the heartbeat comes through it.** Something behind it has been warm for a very long time. There is no way in at the front, and twice as many watchmen as before.","You hold: the fifth · the watch-page: **four left**","Fragments: 3 found","Tomorrow: **the hill behind the hall**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 4, $json${"week":6,"day":4,"title":"Three nights","heading":"Three nights","question":"where is the Seekers' own way in?","steps":[{"t":"say","text":"The grey does not lift at all today. By noon it is as dim as dusk, and you go round the hall by the back lanes with a lamp lit in the middle of the day."},{"t":"say","text":"Behind the hall, the city's highest ground runs out into a rise of cracked, bare rock, split and heaved as if something underneath had shifted a long time ago."},{"t":"act","label":"LOOK FOR THE ONE THAT IS DIFFERENT"},{"t":"say","text":"A hundred cracks, all of them crooked.\n\nAnd one that runs straight up and down, as if it had been ruled."},{"t":"notice","lines":{"Might":{"first":"The rock has closed in on that crack over the years.","second":"It is healing shut. It was cut, once, wide enough for a pack."},"Agility":{"first":"A person could go into it only sideways.","second":"And could not turn round."},"Intellect":{"first":"The hall's back wall and this hill are one piece of rock.","second":"A way into the hill is a way into the hall."},"Charm":{"first":"Every one of you has gone quiet at the same moment.","second":"You have all seen what is standing in it."},"Craft":{"first":"A straight crack in heaved rock.","second":"Somebody made it look like the others, and could not make it crooked."},"Aim":{"first":"In the mouth of the crack there is a shape that is not rock.","second":"It has a helm."}}},{"t":"say","text":"A soldier is standing in the mouth of the crack.\n\nEvery one of them in this city faces the hall. This one has its back to it.\n\nIt is facing you."},{"t":"fight","name":"THE ONE IN THE CRACK","desc":"It does not mean to let you by.","firstLines":null,"strikeFirst":{"on":"player"}},{"t":"say","text":"Between you, it is broken at last, and lies in the mouth of the crack like armour that somebody dropped."},{"t":"say","text":"Yours was the blow that did it. The helm rolls as far as your foot and stops there, facing the hall.","cond":{"on":"fight","won":true}},{"t":"say","text":"You go in sideways, one at a time, with the lamp held out ahead. The rock presses cold against your back and your chest. Deep inside, where the last of the grey daylight gives out, a housing is set into the stone."},{"t":"act","label":"LIFT THE LID"},{"t":"say","text":"It comes away in your hand, beaded with the crack's cold damp.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Past it, the crack ends in blank rock.\n\nCarved beside the dead end, small and deliberate: a full moon, with its whole face scored dark."},{"t":"say","text":"You stand there getting your breath.\n\nThe Seekers' ways open only for their own. Every one of them has opened for you, and for nobody else."},{"t":"act","label":"THEN HOW DID THE ORDER CARRY FOUR STONES INSIDE?"},{"t":"say","text":"Garrick is looking at the blank rock. *\"The Seekers sealed the doors they knew about.\"*"},{"t":"say","text":"There is another door. And the Order has it."},{"t":"say","text":"From the mouth of the crack you can see the same mark, the scored moon, cut high on the side of the slender tower at the city's edge."},{"t":"act","label":"STRIKE THE PAGE"},{"t":"say","text":"By lamplight. Three."},{"t":"say","text":"**What does a full moon struck dark mean? The moon-tower.**","pull":true},{"t":"summary","lines":["**THREE NIGHTS** · Day 4","You earned: `[gold]`","You learned: the Seekers' own way in is **a crack in the hill behind the hall**. It ends in blank rock, beside a carving of a full moon scored dark. And **there is another door** into the hall, one the Seekers never knew about. The Order has it.","You hold: the fifth · the watch-page: **three left**","Fragments: 4 found","Tomorrow: **the moon-tower**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":300}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 5, $json${"week":6,"day":5,"title":"Two nights","heading":"Two nights","question":"what does the scored-dark moon mean?","steps":[{"t":"say","text":"The heartbeat does not wait for dusk any more. It comes at noon. It comes again as you cross the city, and the second time the ground itself trembles."},{"t":"say","text":"The moon-tower stands at the city's edge, slender and tall, with a hundred-odd steps winding up inside it to a round room open to the sky.\n\nHere the old kingdom's sky-watchers kept their records. The walls are cut with the moon's phases, full to dark and back, row on row, year on year."},{"t":"say","text":"Garrick reaches the top a long minute after everyone else, and sits down on the top step with his back to the wall. *\"Give me a minute.\"*\n\nHe waves you on into the room with the back of his hand."},{"t":"notice","lines":{"Might":{"first":"The rows run higher than anyone could reach from the floor.","second":"The watchers cut ledges in the wall for their own feet."},"Agility":{"first":"The steps are worn in the middle, every one, by the same feet night after night.","second":"The top three are hardly worn at all."},"Intellect":{"first":"Row on row, year on year, and never a gap.","second":"Whoever kept this did not miss a night in generations."},"Charm":{"first":"It is patient work, and it is loving.","second":"Somebody was proud of this wall."},"Craft":{"first":"Every moon is cut to the same depth, by the same kind of tool.","second":"All but one."},"Aim":{"first":"Follow the rows round, and they stop.","second":"After that, the stone is bare, all the way back to the door."}}},{"t":"challenge","title":"THE SKY-WATCHERS' WALL","desc":"Thousands of moons. One of them is not like the others.","options":[{"attr":"Craft","verb":"find it by the cut of the chisel"},{"attr":"Might","verb":"climb the watchers' ledges to the highest rows, and read them from there"}],"reward":"+500g","fail":"hours of faded marks by lamplight, in a tower the whole city can see"},{"t":"say","text":"You find it at once, by daylight, with no lamp lit.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It takes hours of reading faded marks by lamplight. You find it. But your lamp has burned half the night in a room open to the sky, and twice, down in the square, a lantern has lifted and looked this way.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"One moon is cut deeper than all the rest: a full moon, struck dark.\n\nAfter it, the wall is blank. They never carved another.\n\nIt is the night he fell."},{"t":"press","title":"THE BLANK STONE","detail":"search it, from the last moon to the door","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"On the ledge under the last moon, a chisel is lying where it was put down. The mallet is beside it.\n\nNobody came back for them.","cond":{"on":"press"}},{"t":"say","text":"Beside the dark moon, a housing gives at a touch."},{"t":"act","label":"TAKE IT"},{"t":"say","text":"It has sat under the open sky for centuries, and it is as cold as the night up here.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"The rows are evenly spaced. The bare stone after them is only stone.\n\nBut you could go on counting."},{"t":"act","label":"COUNT FORWARD, WITH A FINGERTIP"},{"t":"say","text":"Full to dark and back, across the blank wall, at the sky-watchers' own spacing. Year on year. Your finger comes all the way round the room.\n\nIt stops on the doorpost.\n\nThat same moon comes round again in two nights."},{"t":"say","text":"Above you, through the open roof, the moon has come up. Nearly full.\n\n*\"It always comes back,\"* Garrick says quietly, looking up at it."},{"t":"act","label":"STRIKE THE PAGE"},{"t":"say","text":"Two. The page and the wall agree."},{"t":"say","text":"**You have the hour. One piece is left, and the Seekers' way ends at a blank rock with this same moon beside it. Tomorrow is the last day.**","pull":true},{"t":"summary","lines":["**TWO NIGHTS** · Day 5","You earned: `[gold]` · Craft or Might `[growth]`","You learned: the sky-watchers' record **stops on the night he fell**: a full moon, struck dark, and then bare stone. Counted forward, **that moon comes again in two nights.** You have the hour.","You hold: the fifth · the watch-page: **two left**","Fragments: 5 found","Tomorrow: **the crack in the hill**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 6, 6, $json${"week":6,"day":6,"title":"One night","heading":"One night","question":"how does the blank rock open?","steps":[{"t":"say","text":"Everything is worse today. The grey never lifts. The heartbeat comes and comes, and each time the dust sifts down off the rooftops.\n\nAnd between you and the hill, the street is full of soldiers.\n\nThey are not standing.\n\nThey are walking: slowly, stiffly, all the same way. Up the hill, to the hall."},{"t":"notice","lines":{"Might":{"first":"They do not go round what is in their way.","second":"A cart, a fallen door: they walk through it."},"Agility":{"first":"They keep step.","second":"There are gaps between the ranks, and the gaps move at the same pace."},"Intellect":{"first":"Not one has turned its head.","second":"They are not looking for anything. They know where they are going."},"Charm":{"first":"They are a company again.","second":"Whatever else has gone, that has not."},"Craft":{"first":"Iron on stone, in time.","second":"It covers every other sound in the street. It would cover yours."},"Aim":{"first":"At the top of the street, where the hill begins, one of them has stopped.","second":"It is not facing the hall."}}},{"t":"challenge","title":"THE STREET","desc":"There is no way round. There is only across.\nThe hardest yet.","options":[{"attr":"Agility","verb":"through a gap in the ranks, at their pace"},{"attr":"Might","verb":"go in where the ranks are thinnest, and take the knocks"}],"reward":"+500g · **and you strike first**","fail":"one of them sees you, and **it strikes first**"},{"t":"say","text":"You cross between two ranks, close enough to feel the cold coming off the iron. Not one helm turns.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You are halfway when the gap closes. A shoulder of iron takes you in the chest. The rank walks on.\n\nAt the top of the street, one helm has turned.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"At the mouth of the crack, one soldier has stopped walking, and turned round."},{"t":"fight","name":"THE ONE THAT TURNED","desc":"The rest go on up the hill without it.","firstLines":["You strike first.","It strikes first."],"strikeFirst":{"on":"challenge"}},{"t":"say","text":"It goes down across the place where the other one lay. Behind you, the street is still walking."},{"t":"say","text":"You are still on your feet, and it is not. For the length of a breath, not one of the others turns to look.","cond":{"on":"fight","won":true}},{"t":"say","text":"Deep in the crack, at the dead end beside the scored moon, the last fragment is waiting in a cleft at the foot of the blank rock."},{"t":"act","label":"TAKE IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**\n\nThat is six.","fragment":true},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"They settle, as they have five times before, on a ledge of rock at the dead end, with the lamp held close and whoever else is in the crack pressed in behind you to see. This time the map is short, and simple.\n\nIt shows the crack you are standing in. And it shows that the blank rock at the end of it is not rock.\n\nIt is a door, fitted so close that it passes for the hill. Worn into it, in the Seekers' plain hand, is one word.\n\n*here.*\n\nBeside the word is the scored moon. The one way in, and when: the night the moon goes dark."},{"t":"say","text":"You come out of the crack into the evening. The moon is rising over the dead city, round and full and very bright.\n\nTomorrow night it goes dark.\n\nBelow you the soldiers are still climbing. They do not look at you. They are going where you are going."},{"t":"say","text":"Back in the wall room, nobody wants to strike today's stroke."},{"t":"act","label":"STRIKE THE PAGE"},{"t":"say","text":"Slowly. Everyone watches.\n\nOne."},{"t":"say","text":"Garrick pours out the last of his flask into the tin cups: one for each of you, and one more, which he sets on the sill of the slit window, where nobody is sitting.\n\n*\"Drinks are on me,\"* he says. *\"Don't get used to it.\"*"},{"t":"say","text":"**Tomorrow night, when the moon goes dark: through the Seekers' door, into his hall, with the fifth in your hands.**","pull":true},{"t":"summary","lines":["**ONE NIGHT** · Day 6","You earned: `[gold]` · Agility or Might `[growth]`","You learned: the blank rock is **a door**, and it opens **tomorrow night**, when the moon goes dark. The dead are walking up the hill to the hall. Everyone in this city is going to the same room.","You hold: the fifth · the map · the watch-page: **one left**","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · through the Seekers' door, as the moon goes dark"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
